<?php
namespace App\Http\Controllers;
use App\Models\{Book,Category,Member,User,Loan,LoanItem};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Support\Str;

class LibraryController extends Controller
{
    private function json($data, int $status = 200) { return response()->json($data, $status); }
    private function deny(Request $r, array|string $roles) { if (!in_array($r->attributes->get('claims')['role'] ?? '', (array)$roles, true)) return $this->json(['error'=>['code'=>'FORBIDDEN','message'=>'No tiene permisos para esta operación']],403); }
    private function page($query, Request $r): array { $size=min(max((int)$r->query('size',20),1),50); $p=$query->paginate($size,['*'],'page',max((int)$r->query('page',1),1)); return ['items'=>$p->items(),'total'=>$p->total(),'page'=>$p->currentPage(),'size'=>$p->perPage()]; }
    private function token(User $u): string { $body=base64_encode(json_encode(['sub'=>$u->id,'role'=>$u->role,'exp'=>time()+28800])); return $body.'.'.hash_hmac('sha256',$body,env('JWT_SECRET','change-me')); }
    public function login(Request $r) { $d=$r->validate(['username'=>'required|string','password'=>'required|string']); $u=User::where('username',strtolower(trim($d['username'])))->first(); if(!$u||!Hash::check($d['password'],$u->password_hash)) return $this->json(['error'=>['code'=>'INVALID_CREDENTIALS','message'=>'Usuario o clave inválidos']],401); return $this->json(['access_token'=>$this->token($u),'token_type'=>'Bearer','expires_in'=>28800,'role'=>$u->role]); }
    public function createLibrarian(Request $r) { if($x=$this->deny($r,'admin')) return $x; $d=$r->validate(['username'=>'required|string','password'=>'required|string|min:8','role'=>'required|in:librarian']); $name=strtolower(trim($d['username'])); if(User::where('username',$name)->exists()) return $this->json(['error'=>['code'=>'USERNAME_TAKEN','message'=>'El nombre de usuario ya existe']],409); $u=User::create(['id'=>(string)Str::uuid(),'username'=>$name,'password_hash'=>Hash::make($d['password']),'role'=>'librarian']); return $this->json(['id'=>$u->id,'username'=>$u->username,'role'=>$u->role],201); }
    public function categories() { return $this->json(Category::orderBy('name')->get()); }
    public function index(Request $r) { $q=Book::whereNull('deleted_at')->when($r->q,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','ilike',"%$v%")->orWhere('author','ilike',"%$v%")))->when($r->category_id,fn($q,$v)=>$q->where('category_id',$v))->orderBy('title'); return $this->json($this->page($q,$r)); }
    public function show(string $book) { $b=Book::whereNull('deleted_at')->find($book); return $b?$this->json($b):$this->json(['error'=>['code'=>'NOT_FOUND','message'=>'Libro no encontrado']],404); }
    public function store(Request $r) { if($x=$this->deny($r,'admin')) return $x; $d=$r->validate(['title'=>'required|string|max:250','author'=>'required|string|max:200','isbn'=>'required|digits:13','category_id'=>'required|exists:category,id','total_copies'=>'required|integer|min:1']); if(Book::where('isbn',$d['isbn'])->whereNull('deleted_at')->exists()) return $this->json(['error'=>['code'=>'ISBN_TAKEN','message'=>'El ISBN ya existe']],409); return $this->json(Book::create(array_merge($d,['id'=>(string)Str::uuid(),'available_copies'=>$d['total_copies'],'version'=>0])),201); }
    public function update(Request $r,string $book) { if($x=$this->deny($r,'admin')) return $x; $b=Book::whereNull('deleted_at')->findOrFail($book); $d=$r->validate(['title'=>'sometimes|string|max:250','author'=>'sometimes|string|max:200','category_id'=>'sometimes|exists:category,id','total_copies'=>'sometimes|integer|min:1']); if(isset($d['total_copies'])) { $delta=$d['total_copies']-$b->total_copies; if($b->available_copies+$delta<0) return $this->json(['error'=>['code'=>'INSUFFICIENT_COPIES','message'=>'El total no puede dejar disponibles negativos']],422); $d['available_copies']=$b->available_copies+$delta; } $b->update($d); return $this->json($b->fresh()); }
    public function destroy(Request $r,string $book) { if($x=$this->deny($r,'admin')) return $x; $b=Book::whereNull('deleted_at')->findOrFail($book); if(LoanItem::where('book_id',$b->id)->whereNull('returned_at')->exists()) return $this->json(['error'=>['code'=>'BOOK_HAS_OPEN_LOANS','message'=>'El libro tiene préstamos abiertos']],409); $b->update(['deleted_at'=>now()]); return response()->noContent(); }
    public function cover(Request $r,string $book) { if($x=$this->deny($r,'admin')) return $x; $r->validate(['cover'=>'required|file|mimes:jpg,jpeg,png|max:2048']); $b=Book::findOrFail($book); $key=(string)Str::uuid().'.'.$r->file('cover')->extension(); $r->file('cover')->storeAs('covers',$key); $b->update(['cover_key'=>$key]); return $this->json(['cover_key'=>$key]); }
    public function coverFile(string $book) { $b=Book::whereNull('deleted_at')->findOrFail($book); if(!$b->cover_key||!Storage::exists('covers/'.$b->cover_key)) return $this->json(['error'=>['code'=>'NOT_FOUND','message'=>'Portada no encontrada']],404); return Storage::download('covers/'.$b->cover_key); }
    public function members(Request $r) { $q=Member::when($r->q,fn($q,$v)=>$q->where(fn($q)=>$q->where('full_name','ilike',"%$v%")->orWhere('document_number',$v)))->orderBy('full_name'); return $this->json($this->page($q,$r)); }
    public function showMember(string $member) { $m=Member::find($member); return $m?$this->json($m):$this->json(['error'=>['code'=>'NOT_FOUND','message'=>'Socio no encontrado']],404); }
    public function storeMember(Request $r) { $d=$r->validate(['full_name'=>'required|string|max:200','document_number'=>'required|string|max:30']); if(Member::where('document_number',$d['document_number'])->exists()) return $this->json(['error'=>['code'=>'DOCUMENT_TAKEN','message'=>'El documento ya existe']],409); return $this->json(Member::create(array_merge($d,['id'=>(string)Str::uuid()])),201); }
    public function storeLoan(Request $r) { $d=$r->validate(['member_id'=>'required|exists:member,id','items'=>'required|array|min:1|max:3','items.*.book_id'=>'required|distinct|exists:book,id']); $now=now(); return DB::transaction(function()use($d,$r,$now){ $open=LoanItem::whereHas('loan',fn($q)=>$q->where('member_id',$d['member_id']))->whereNull('returned_at')->count(); if($open+count($d['items'])>3) return $this->json(['error'=>['code'=>'MEMBER_LIMIT_EXCEEDED','message'=>"El socio ya tiene $open libros sin devolver"]],422); if(LoanItem::whereHas('loan',fn($q)=>$q->where('member_id',$d['member_id']))->whereNull('returned_at')->where('due_at','<',$now)->exists()) return $this->json(['error'=>['code'=>'MEMBER_HAS_OVERDUE','message'=>'El socio tiene libros vencidos']],409); $loan=Loan::create(['id'=>(string)Str::uuid(),'member_id'=>$d['member_id'],'loaned_by_user_id'=>$r->attributes->get('claims')['sub'],'loaned_at'=>$now]); foreach($d['items'] as $i){$b=Book::whereNull('deleted_at')->where('id',$i['book_id'])->where('available_copies','>',0)->lockForUpdate()->first(); if(!$b) abort(response()->json(['error'=>['code'=>'BOOK_NOT_AVAILABLE','message'=>'No hay ejemplares disponibles']],409)); $b->decrement('available_copies');$b->increment('version'); LoanItem::create(['id'=>(string)Str::uuid(),'loan_id'=>$loan->id,'book_id'=>$b->id,'book_title'=>$b->title,'isbn'=>$b->isbn,'category_name'=>Category::find($b->category_id)->name,'due_at'=>$now->copy()->addDays(14)]); } return $this->json($this->loanData($loan->fresh('items')),201); }); }
    private function loanData(Loan $l): array { $over=$l->items->contains(fn($i)=>!$i->returned_at&&$i->due_at<now()); $a=$l->toArray(); $a['status']=$l->items->every(fn($i)=>(bool)$i->returned_at)?'closed':($over?'overdue':'open'); return $a; }
    public function loan(string $id) { $l=Loan::with('items')->find($id); return $l?$this->json($this->loanData($l)):$this->json(['error'=>['code'=>'NOT_FOUND','message'=>'Préstamo no encontrado']],404); }
    public function loans(Request $r) { $p=$this->page(Loan::with('items')->when($r->member_id,fn($q,$v)=>$q->where('member_id',$v))->orderByDesc('loaned_at'),$r); $p['items']=array_map(fn($l)=>$this->loanData($l),$p['items']); return $this->json($p); }
    public function returnItem(string $loan,string $item) { $x=DB::transaction(function()use($loan,$item){$i=LoanItem::where('loan_id',$loan)->where('id',$item)->lockForUpdate()->firstOrFail();if($i->returned_at)return null;$i->update(['returned_at'=>now()]);Book::where('id',$i->book_id)->increment('available_copies');return $i->fresh();}); return $x?$this->json($x):$this->json(['error'=>['code'=>'ITEM_ALREADY_RETURNED','message'=>'La línea ya fue devuelta']],409); }
    public function overdue() { return $this->json(['items'=>LoanItem::with('loan')->whereNull('returned_at')->where('due_at','<',now())->orderBy('due_at')->get()->map(fn($i)=>['loan_id'=>$i->loan_id,'item_id'=>$i->id,'book_title'=>$i->book_title,'member_name'=>Member::find($i->loan->member_id)->full_name,'due_at'=>$i->due_at,'days_late'=>$i->due_at->diffInDays(now())])]); }
    public function report(Request $r) { if($x=$this->deny($r,'admin')) return $x; $d=$r->validate(['from'=>'required|date','to'=>'required|date']); if($d['to']<$d['from']) return $this->json(['error'=>['code'=>'INVALID_DATE_RANGE','message'=>'El fin debe ser posterior o igual al inicio']],422); $rows=LoanItem::select('book_id','book_title','category_name',DB::raw('count(*) as times_borrowed'))->whereHas('loan',fn($q)=>$q->whereBetween('loaned_at',[$d['from'].' 00:00:00',$d['to'].' 23:59:59']))->groupBy('book_id','book_title','category_name')->orderByDesc('times_borrowed')->orderBy('book_title')->get(); return $this->json(['from'=>$d['from'],'to'=>$d['to'],'rows'=>$rows]); }
}
